import{_ as n,o as s,c as a,a5 as t}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"46. Error Checking with errno and perror","description":"The Little Book of C — 46. Error Checking with errno and perror","frontmatter":{"title":"46. Error Checking with errno and perror","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Input Output and Files"],"description":"The Little Book of C — 46. Error Checking with errno and perror","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":46,"sidebarWeight":46,"lang":"en-US","alternateEn":"/posts/c教程/en-US/05-Input Output and Files/046-Error Checking with errno and perror","alternateZh":"/posts/c教程/zh-CN/05-输入输出与文件/046-Error Checking with errno and perror"},"headers":[],"relativePath":"posts/c教程/en-US/05-Input Output and Files/046-Error Checking with errno and perror.md","filePath":"posts/c教程/en-US/05-Input Output and Files/046-Error Checking with errno and perror.md","lastUpdated":1790163617000}'),r={name:"posts/c教程/en-US/05-Input Output and Files/046-Error Checking with errno and perror.md"};function o(i,e,p,l,d,c){return s(),a("div",null,[...e[0]||(e[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/05-输入输出与文件/046-Error Checking with errno and perror)</p><p>Even the best-written C programs can encounter errors, missing files, permission issues, division by zero, or failed memory allocations. Unlike some languages that throw exceptions, C reports errors manually using return values and a global variable named<code>errno</code>.</p><p>Understanding how to use<code>errno</code>,<code>perror()</code>, and<code>strerror()</code> is essential for writing robust, production-grade C programs that fail gracefully and informatively.</p><h4 id="the-idea-behind-errno" tabindex="-1">The Idea Behind errno <a class="header-anchor" href="#the-idea-behind-errno" aria-label="Permalink to &quot;The Idea Behind errno&quot;">​</a></h4><p><code>errno</code> is a global integer (declared in<code>&lt;errno.h&gt;</code>) that stores an error code whenever a library function fails.</p><ul><li>On success, most functions leave<code>errno</code> unchanged.</li><li>On failure, they typically set<code>errno</code> and return an error value (often<code>NULL</code>,<code>-1</code>, or<code>0</code> depending on the function).</li><li>You must check the return value first, only then should you inspect<code>errno</code>.</li></ul><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *fp = fopen(&quot;missing.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        printf(&quot;Error code: %d\\n&quot;, errno);</span></span>
<span class="line"><span>        perror(&quot;fopen failed&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error code: 2</span></span>
<span class="line"><span>fopen failed: No such file or directory</span></span></code></pre></div><h4 id="common-errno-codes" tabindex="-1">Common errno Codes <a class="header-anchor" href="#common-errno-codes" aria-label="Permalink to &quot;Common errno Codes&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td>2</td><td><code>ENOENT</code></td><td>No such file or directory</td></tr><tr><td>13</td><td><code>EACCES</code></td><td>Permission denied</td></tr><tr><td>12</td><td><code>ENOMEM</code></td><td>Not enough memory</td></tr><tr><td>22</td><td><code>EINVAL</code></td><td>Invalid argument</td></tr><tr><td>17</td><td><code>EEXIST</code></td><td>File already exists</td></tr><tr><td>5</td><td><code>EIO</code></td><td>Input/output error</td></tr><tr><td>111</td><td><code>ECONNREFUSED</code></td><td>Connection refused (network)</td></tr></tbody></table><p>Include<code>&lt;errno.h&gt;</code> to use these symbolic names:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (errno == ENOENT) printf(&quot;File missing.\\n&quot;);</span></span></code></pre></div><h4 id="using-perror" tabindex="-1">Using perror() <a class="header-anchor" href="#using-perror" aria-label="Permalink to &quot;Using perror()&quot;">​</a></h4><p><code>perror()</code> prints a human-readable error message to<code>stderr</code>, based on the current value of<code>errno</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>perror(&quot;File open error&quot;);</span></span></code></pre></div><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *f = fopen(&quot;ghost.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!f)</span></span>
<span class="line"><span>        perror(&quot;Unable to open file&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Unable to open file: No such file or directory</span></span></code></pre></div><h4 id="using-strerror" tabindex="-1">Using strerror() <a class="header-anchor" href="#using-strerror" aria-label="Permalink to &quot;Using strerror()&quot;">​</a></h4><p>If you want to use the error message in your own formatted output, use<code>strerror()</code> from<code>&lt;string.h&gt;</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *f = fopen(&quot;/root/secret.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>    if (!f)</span></span>
<span class="line"><span>        printf(&quot;Error (%d): %s\\n&quot;, errno, strerror(errno));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error (13): Permission denied</span></span></code></pre></div><h4 id="tiny-code-robust-file-reader" tabindex="-1">Tiny Code: Robust File Reader <a class="header-anchor" href="#tiny-code-robust-file-reader" aria-label="Permalink to &quot;Tiny Code: Robust File Reader&quot;">​</a></h4><p>Here’s a simple file reader that checks for errors at every step:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>int main(int argc, char *argv[]) {</span></span>
<span class="line"><span>    if (argc != 2) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Usage: %s &lt;filename&gt;\\n&quot;, argv[0]);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    FILE *fp = fopen(argv[1], &quot;r&quot;);</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Error opening %s: %s\\n&quot;, argv[1], strerror(errno));</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    char buf[128];</span></span>
<span class="line"><span>    while (fgets(buf, sizeof(buf), fp))</span></span>
<span class="line"><span>        printf(&quot;%s&quot;, buf);</span></span>
<span class="line"><span>    if (ferror(fp)) {</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Error reading file: %s\\n&quot;, strerror(errno));</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Usage:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./readfile poem.txt</span></span></code></pre></div><p>If the file is missing:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error opening poem.txt: No such file or directory</span></span></code></pre></div><h4 id="clearing-and-resetting-errno" tabindex="-1">Clearing and Resetting errno <a class="header-anchor" href="#clearing-and-resetting-errno" aria-label="Permalink to &quot;Clearing and Resetting errno&quot;">​</a></h4><p>Some functions may set<code>errno</code> even if they succeed later. To be safe, you can clear it before a call:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>errno = 0;</span></span>
<span class="line"><span>FILE *f = fopen(&quot;file.txt&quot;, &quot;r&quot;);</span></span>
<span class="line"><span>if (!f) perror(&quot;fopen&quot;);</span></span></code></pre></div><p>This ensures you don’t read a leftover error from an earlier operation.</p><h4 id="checking-other-system-errors" tabindex="-1">Checking Other System Errors <a class="header-anchor" href="#checking-other-system-errors" aria-label="Permalink to &quot;Checking Other System Errors&quot;">​</a></h4><p><code>errno</code> isn’t limited to file I/O, it applies to many system calls and library functions:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    FILE *f = fopen(&quot;/dev/full&quot;, &quot;w&quot;); // special Linux device that fails on write</span></span>
<span class="line"><span>    if (f) {</span></span>
<span class="line"><span>        if (fputc(&#39;A&#39;, f) == EOF)</span></span>
<span class="line"><span>            perror(&quot;Write failed&quot;);</span></span>
<span class="line"><span>        fclose(f);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Write failed: No space left on device</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p><code>errno</code> and its helpers (<code>perror</code>,<code>strerror</code>) make your programs explain themselves when things go wrong. This is vital for:</p><ul><li>System tools that must report specific error causes</li><li>Debugging production code</li><li>Writing portable, maintainable programs</li></ul><p>Good C developers never just “fail silently.”</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Open a file that doesn’t exist, then create it and try again.</li><li>Simulate a read error by using<code>ferror()</code> after reading a closed file.</li><li>Try writing to a directory (<code>fopen(&quot;/tmp&quot;, &quot;w&quot;)</code>) and inspect<code>errno</code>.</li><li>Print all known error codes and messages using a loop and<code>strerror()</code>.</li><li>Write a small “safe_open” function that wraps<code>fopen</code> with error reporting.</li></ol><p>With error handling mastered, you now know how to make C programs both informative and reliable. Next, you’ll explore command-line arguments (<code>argc</code>,<code>argv</code>), the gateway to building flexible, scriptable tools that process user input dynamically.</p>`,49)])])}const g=n(r,[["render",o]]);export{h as __pageData,g as default};
